            ["Curve.Lock.Mapping.Slightly.Desc"] = "\u8fd9\u662f\u6709\u529b\u5239\u8f66\u5f00\u59cb\u7684\u4f4d\u7f6e\uff0c\u539f\u59cb\u503c\u4e3a 30\u2014\u2014\u8db3\u591f\u4f46\u5c1a\u672a\u8fbe\u5230\u5b8c\u7f8e\u3002\u5c06\u5239\u8f66\u529b\u5ea6\u4fdd\u6301\u5728\u6b64\u503c\u4ee5\u4e0a\u3001\u5b8c\u7f8e\u503c\u4ee5\u4e0b\u7684\u533a\u95f4\u53ef\u83b7\u5f97\u826f\u597d\u7684\u5239\u8f66\u6548\u679c\uff1b\u4fdd\u6301\u5728\u5b8c\u7f8e\u503c\u5230\u6700\u5927\u6293\u5730\u529b\u4e4b\u95f4\u7684\u533a\u95f4\u5219\u53ef\u83b7\u5f97\u7406\u60f3\u7684\u5239\u8f66\u548c\u6700\u4f73\u6548\u679c\u3002\u5c06\u6b64\u503c\u8c03\u4f4e\u53ef\u4ee5\u5728\u6b63\u5e38\u3001\u8f7b\u67d4\u5239\u8f66\u65f6\u4e0d\u4ea7\u751f\u632f\u52a8\u3002",
