            ["Curve.Lock.MaxGripOnly.Slightly.Desc"] = "\u4f60\u521a\u521a\u8fdb\u5165\u8f6e\u80ce\u7684\u5de5\u4f5c\u8303\u56f4\u2014\u2014\u4f4e\u4e8e\u6b64\u503c\u65f6\u4ecd\u6709\u4f59\u91cf\uff0c\u9ad8\u4e8e\u6b64\u503c\u65f6\u5219\u5728\u771f\u6b63\u4f7f\u7528\u6293\u5730\u529b\u3002\u5c06\u6b64\u503c\u8c03\u4f4e\u53ef\u4ee5\u5728\u6b63\u5e38\u3001\u8f7b\u67d4\u5239\u8f66\u65f6\u4e0d\u4ea7\u751f\u632f\u52a8\u3002",
            ["Curve.Lock.MaxGripOnly.Ideal.Desc"] = "\u4f60\u6b63\u5904\u4e8e\u7406\u60f3\u5239\u8f66\u533a\u95f4\u7684\u8fb9\u7f18\u2014\u2014\u5373\u5c06\u8fbe\u5230\u8f66\u8f6e\u5f00\u59cb\u62b1\u6b7b\u4e4b\u524d\u7684\u6700\u5927\u6709\u6548\u5239\u8f66\u529b\u5ea6\u3002\u8fd9\u662f\u6700\u4f73\u4f4d\u7f6e\uff1a\u5c06\u5239\u8f66\u4fdd\u6301\u5728\u6b64\u5904\u4ee5\u83b7\u5f97\u6700\u5feb\u7684\u51cf\u901f\u3002",
