            ["Curve.Slip.AnchorNote"] = "\u6bcf\u4e00\u884c\u7684\u542b\u4e49\u662f\u201c\u5f53\u6253\u6ed1\u503c\u8fbe\u5230\u8fd9\u4e2a\u539f\u59cb\u503c\u65f6\uff0c\u53d1\u9001\u8fd9\u4e2a\u8f93\u51fa\u503c\u201d\u3002\u9ed8\u8ba4\u7684\u66f2\u7ebf\u9884\u8bbe\u53d1\u9001 30 \u5bf9\u5e94 10\u300162 \u5bf9\u5e94 35 \u548c 78 \u5bf9\u5e94 70\u2014\u2014\u4e0e\u62b1\u6b7b\u66f2\u7ebf\u91c7\u7528\u76f8\u540c\u7684\u533a\u95f4\u8fb9\u754c\uff0c\u5e76\u4e14\u7406\u60f3\u533a\u95f4\u5185\u7684\u5dee\u8ddd\u4e5f\u8fdb\u4e00\u6b65\u7f29\u5c0f\uff1a\u8f7b\u6cb9\u95e8\u65f6\u51e0\u4e4e\u6ca1\u6709\u53cd\u9988\uff0c\u7406\u60f3\u533a\u95f4\u5185\u6709\u660e\u663e\u7684\u63d0\u793a\uff0c\u63a5\u8fd1\u7275\u5f15\u529b\u6781\u9650\u65f6\u5219\u6709\u5f3a\u70c8\u7684\u63d0\u793a\u3002\u6bcf\u4e2a\u8bbe\u5b9a\u70b9\u81ea\u8eab\u7684\u5e73\u6ed1\u8303\u56f4\u4f1a\u5c06\u5176\u62d3\u5bbd\u4e3a\u4e00\u5c0f\u6bb5\u5e73\u53f0\uff0c\u800c\u4e0d\u662f\u7a7f\u8fc7\u5b83\u7684\u9661\u5ced\u659c\u5761\u2014\u2014\u9ed8\u8ba4\u60c5\u51b5\u4e0b\uff0c\u7406\u60f3\u548c\u6700\u5927\u6293\u5730\u529b\u5e73\u53f0\u6b63\u597d\u843d\u5728\u5171\u4eab\u7684 60 \u548c 80 \u533a\u95f4\u8fb9\u754c\u4e0a\uff0860-64 \u548c 76-80\uff09\uff0c\u533a\u95f4\u5185\u90e8\u5e73\u6ed1\u8fc7\u6e21\uff0c\u533a\u95f4\u5916\u90e8\u5219\u5feb\u901f\u4e0a\u5347\u6216\u4e0b\u964d\u3002",
            ["Curve.Slip.StartPoint.Desc"] = "\u4f4e\u4e8e\u6b64\u539f\u59cb\u503c\u65f6\uff0c\u8f93\u51fa\u4f1a\u4fdd\u6301\u5728\u53f3\u4fa7\u663e\u793a\u7684\u8d77\u59cb\u8f93\u51fa\u503c\uff08\u9ed8\u8ba4 0\u2014\u2014\u5b8c\u5168\u6ca1\u6709\u8f93\u51fa\uff09\u3002\u5982\u679c\u8f7b\u6cb9\u95e8\u65f6\u632f\u52a8\u8fc7\u591a\uff0c\u53ef\u4ee5\u63d0\u9ad8\u6b64\u539f\u59cb\u503c\u3002\u9ed8\u8ba4\u503c\u4e3a {0}\u3002",
