            ["Curve.Slip.EndPoint.Desc"] = "\u8fbe\u5230\u6216\u8d85\u8fc7\u6b64\u539f\u59cb\u503c\u65f6\uff0c\u8f66\u8f6e\u5df2\u5b8c\u5168\u6253\u6ed1\uff0c\u52a8\u529b\u6b63\u5728\u88ab\u6d6a\u8d39\uff0c\u8f93\u51fa\u4f1a\u4fdd\u6301\u5728\u53f3\u4fa7\u663e\u793a\u7684\u7ed3\u675f\u8f93\u51fa\u503c\uff08\u9ed8\u8ba4 100\u2014\u2014\u6ee1\u5f3a\u5ea6\uff09\u3002\u964d\u4f4e\u7ed3\u675f\u8f93\u51fa\u503c\u53ef\u9650\u5236\u8be5\u63d0\u793a\u7684\u6700\u5927\u5f3a\u5ea6\u3002\u9ed8\u8ba4\u503c\u4e3a {0}\u3002",
