            ["GForce.Shake.Note"] = "\u5f00\u542f\u540e\uff0c\u8f66\u8f6e\u62b1\u6b7b/\u6253\u6ed1\u4f1a\u5c06\u6bcf\u4e00\u5bf9\u5de6\u53f3\u632f\u52a8\u57ab\u53d8\u4e3a\u4ea4\u66ff\u6296\u52a8\uff0c\u5177\u4f53\u5e94\u7528\u65b9\u5f0f\u7531\u4e0b\u65b9\u6a21\u5f0f\u51b3\u5b9a\u3002\u672a\u63a5\u5165\u62b1\u6b7b/\u6253\u6ed1\u4fe1\u53f7\u65f6\u4fdd\u6301\u9759\u9ed8\u3002",
            ["GForce.Shake.Angle.Enable"] = "整合滑移角",
            ["GForce.Shake.Angle.Note"] = "开启后，映射后的滑移角可单独触发同一抖动；抱死、打滑与滑移角（各自乘以自身缩放系数）中的较大者决定抖动强度。与下方的模式、手感和触发阈值共用。",
            ["GForce.Shake.Mode.Label"] = "\u6296\u52a8\u5e94\u7528\u4e8e",
            ["GForce.Shake.Mode.PerChannel"] = "\u5404\u901a\u9053\u81ea\u8eab\u7684G\u529b\u6c34\u5e73",
            ["GForce.Shake.Mode.AllGForce"] = "\u6240\u6709\u901a\u9053\uff08\u8ddf\u968fG\u529b\u5f3a\u5ea6\uff09",
            ["GForce.Shake.Mode.AllLockSlip"] = "所有通道（仅按抱死/打滑/滑移角强度）",
            ["GForce.Shake.Mode.HigherOfBoth"] = "G力与车轮抱死/打滑/滑移角取较大者",
            ["GForce.Shake.Mode.PerChannel.Desc"] = "每个运行中的通道围绕其自身当前的G力水平抖动，强度随车轮抱死、打滑或滑移角的程度增强或减弱。未被G力驱动的通道保持静止。",
            ["GForce.Shake.Mode.AllGForce.Desc"] = "由最强通道的G力水平决定统一的抖动强度，并以相同强度应用于所有通道——因此安静的通道也会抖动。强度仍随车轮抱死、打滑或滑移角的程度变化。",
            ["GForce.Shake.Mode.AllLockSlip.Desc"] = "所有通道以相同强度抖动，强度仅取决于车轮抱死/打滑/滑移角水平。完全忽略G力，因此无论刹车还是滑行，抖动强度都一样。",
            ["GForce.Shake.Mode.HigherOfBoth.Desc"] = "每个通道完全保留「各通道自身」模式下的 G 力动画——相同的最小值、相同的波形——车轮（抱死、打滑或滑移角）只会**抬高其上限**。轻微抱死只是在 G 力体感之上增加一点幅度；而车轮达到极限时会把所有通道都推到满幅，此时无论 G 力如何，抖动都占主导。",
            ["GForce.Motion.SustainTau.Hint"] = "数值越大，稳定后的强度越缓慢、越平滑地建立；越小则几乎立即到位。",
            ["GForce.Motion.TransientTau.Hint"] = "一次突然的输入能让扫动继续多久。数值越大，踏板稳定后行程还会继续推进越远；越小则几乎立即停住。",
            ["GForce.Motion.TransientGain.Hint"] = "数值越大，扫动越快穿过三个震动垫；越小则同样输入下行程更长、更慢、更平滑。",
            ["GForce.Motion.RetriggerStrictness.Label"] = "重新触发严格度 (0.1-5)",
            ["GForce.Motion.RetriggerStrictness.Hint"] = "在弯中要多用力地重踩踏板，才会重新触发行程动画。数值越大，只有果断的重踩才会重启；越小则更容易重启，在持续刹车时可能显得吹噪。",
            ["GForce.Motion.AutoTransitionScale.Hint"] = "数值越大，在最大值尚在学习时行程越宽、越明显；1.0 表示不做额外放大。",
            ["GForce.Motion.FixedTransitionScale.Hint"] = "同上，但适用于手动设定的最大值。数值越大行程越明显；1.0 表示不放大。",
            ["GForce.Shake.Feeling.Label"] = "抖动感觉",
            ["GForce.Shake.Feeling.Opposite"] = "反相（左右交替）",
            ["GForce.Shake.Feeling.Same"] = "同相（两侧同步）",
            ["GForce.Shake.Feeling.Blending"] = "错相（一侧领先）",
            ["GForce.Shake.Feeling.Opposite.Desc"] = "两个震动垫相差半个周期——一侧处于峰值时另一侧处于谷值，感觉像振动在左右移动。两侧总量几乎不变，因此是三者中最含蓄的一种。",
            ["GForce.Shake.Feeling.Same.Desc"] = "两侧在同一时刻做同样的事。三者中体感最强，因为整对震动垫一起涨落——代价是不再携带任何左右方位信息。",
            ["GForce.Shake.Feeling.Blending.Desc"] = "两侧相差四分之一：都从最高点开始，一侧立即下降而另一侧仍在保持。既保留左右移动，又让总量起伏，这正是让人真正感到「抖动」的组合。它使用固定的保持比例，因此保持项被隐藏。",
            ["GForce.Shake.Preview.Caption"] = "一秒钟的输出",
            ["GForce.Shake.Preview.Legend"] = "绿色＝左侧，红色＝右侧，依据左边的设置绘制。",
            ["GForce.Test.Header"] = "效果测试",
            ["GForce.Test.Note"] = "手动驱动输出，便于设置 ShakeIt 的各项强度。本页所有 G 力设置都会生效，因此这里的手感就是赛道上的手感。",
            ["GForce.Test.Rate.Label"] = "模拟频率 (Hz)",
            ["GForce.Test.Rate.Hint"] = "每秒产生多少帧模拟数据。60 与常见游戏一致。",
